using System.Windows.Forms;
namespace Musikbox {
 public class AppFileDialog:ModernForm {
  public readonly TextBox SearchInput=new StudioTextBox{Dock=DockStyle.Fill,AccessibleName="Datei- und Ordnernamen im geöffneten Ordner suchen"};
  readonly bool save,folders;string current,selectionText="";bool updating;
  public readonly TextBox Address=new StudioTextBox{Dock=DockStyle.Fill},NameInput=new StudioTextBox{Dock=DockStyle.Fill};
  public readonly ListView Entries=new StudioListView{Dock=DockStyle.Fill,View=System.Windows.Forms.View.Details,FullRowSelect=true,HideSelection=false};
  public readonly ComboBox FileTypes=new StudioComboBox{Dock=DockStyle.Fill,DropDownStyle=ComboBoxStyle.DropDownList};
  readonly ComboBox places=new StudioComboBox{Dock=DockStyle.Fill,DropDownStyle=ComboBoxStyle.DropDownList};
  public readonly Label State=new Label{Dock=DockStyle.Bottom,Height=32,AutoEllipsis=true};
  public string Filter {get;set;}public string FileName {get;set;}public string[] FileNames {get;private set;}public bool Multiselect {get;set;}public string InitialDirectory {get;set;}public string Description {get;set;}
  public string Title {get{return Text;}set{Text=value;}}public string SelectedPath {get{return FileName;}set{FileName=value;}}
  public bool StartAtDrives {get;set;}
  public string CurrentDirectory {get{return current;}}
  class Entry {public string Path;public bool Folder;}
  public AppFileDialog(bool save=false,bool folders=false){
   this.save=save;this.folders=folders;Text=folders?"Ordner auswählen":save?"Datei speichern":"Datei öffnen";Width=920;Height=620;MinimumSize=new Size(680,430);StartPosition=FormStartPosition.CenterParent;Font=new Font("Segoe UI",10);Padding=new Padding(10);FileNames=new string[0];
   var top=new TableLayoutPanel{Dock=DockStyle.Top,Height=36,ColumnCount=4};top.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,40));top.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));top.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,70));top.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,180));var up=new Button{Text="↑",Dock=DockStyle.Fill,AccessibleName="Übergeordneter Ordner"};var go=new Button{Text="Öffnen",Dock=DockStyle.Fill};top.Controls.Add(up,0,0);top.Controls.Add(Address,1,0);top.Controls.Add(go,2,0);top.Controls.Add(places,3,0);
   up.Click+=(s,e)=>Up();go.Click+=(s,e)=>Navigate(Address.Text);Address.KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Enter){e.SuppressKeyPress=true;Navigate(Address.Text);}};places.SelectionChangeCommitted+=(s,e)=>{if(places.SelectedItem!=null){if(places.SelectedItem.ToString()=="Laufwerke")ShowDrives();else Navigate(places.SelectedItem.ToString());}};places.DropDown+=(s,e)=>LoadPlaces();
   Entries.Columns.Add("Name",480);Entries.Columns.Add("Art",110);Entries.Columns.Add("Größe",120);Entries.SelectedIndexChanged+=(s,e)=>{if(updating)return;var selected=Selected();selectionText=String.Join(" ",selected.Where(x=>folders||!x.Folder).Select(x=>"\""+(folders?x.Path:Path.GetFileName(x.Path))+"\""));NameInput.Text=selectionText;};Entries.DoubleClick+=(s,e)=>{var selected=Selected();if(selected.Length==1&&selected[0].Folder)Navigate(selected[0].Path);else AcceptSelection();};Entries.KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Enter){e.SuppressKeyPress=true;var selected=Selected();if(selected.Length==1&&selected[0].Folder)Navigate(selected[0].Path);else AcceptSelection();}};
   var bottom=new TableLayoutPanel{Dock=DockStyle.Bottom,Height=76,ColumnCount=3,RowCount=2};bottom.RowStyles.Add(new RowStyle(SizeType.Absolute,34));bottom.RowStyles.Add(new RowStyle(SizeType.Absolute,34));bottom.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,100));bottom.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));bottom.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,150));bottom.Controls.Add(new Label{Text=folders?"Ordner":"Dateiname",Dock=DockStyle.Fill},0,0);bottom.Controls.Add(NameInput,1,0);var ok=new Button{Text=save?"Speichern":folders?"Ordner auswählen":"Auswählen",Dock=DockStyle.Fill};bottom.Controls.Add(ok,2,0);bottom.Controls.Add(FileTypes,1,1);var cancel=new Button{Text="Abbrechen",DialogResult=DialogResult.Cancel,Dock=DockStyle.Fill};bottom.Controls.Add(cancel,2,1);var create=new Button{Text="Neuer Ordner",Dock=DockStyle.Fill};bottom.Controls.Add(create,0,1);create.Click+=(s,e)=>NewFolder();ok.Click+=(s,e)=>AcceptSelection();AcceptButton=ok;CancelButton=cancel;FileTypes.SelectedIndexChanged+=(s,e)=>{if(current!=null)Navigate(current);};
   var searchRow=new TableLayoutPanel{Dock=DockStyle.Top,Height=32,ColumnCount=2};searchRow.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,180));searchRow.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));searchRow.Controls.Add(new Label{Text="Suche in diesem Ordner",Dock=DockStyle.Fill},0,0);searchRow.Controls.Add(SearchInput,1,0);
   SearchInput.TextChanged+=(s,e)=>{if(!updating&&current!=null)Navigate(current);};
   Controls.Add(Entries);Controls.Add(State);Controls.Add(bottom);Controls.Add(searchRow);Controls.Add(top);
  }
  protected override void OnLoad(EventArgs e){
   Entries.MultiSelect=Multiselect&&!folders&&!save;if(!String.IsNullOrWhiteSpace(Description))Text=Description;
   string[] parts=(Filter??"Alle Dateien|*.*").Split('|');for(int i=0;i+1<parts.Length;i+=2)FileTypes.Items.Add(parts[i]+" ("+parts[i+1]+")");if(FileTypes.Items.Count==0)FileTypes.Items.Add("Alle Dateien (*.*)");FileTypes.SelectedIndex=0;FileTypes.Visible=!folders;LoadPlaces();
   if(StartAtDrives){ShowDrives();base.OnLoad(e);return;}
   string initial=InitialDirectory;if(String.IsNullOrWhiteSpace(initial))initial=StudioPreferences.Folder(save?"DateiSpeichern":folders?"Ordner":"DateiOeffnen");if(!String.IsNullOrWhiteSpace(FileName)){try{if(Directory.Exists(FileName))initial=FileName;else if(Path.IsPathRooted(FileName))initial=Path.GetDirectoryName(FileName);}catch{}}
   if(String.IsNullOrWhiteSpace(initial)||!Directory.Exists(initial))initial=Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments);if(String.IsNullOrWhiteSpace(initial)||!Directory.Exists(initial))initial=Environment.CurrentDirectory;Navigate(initial);NameInput.Text=folders?current:Path.GetFileName(FileName??"");base.OnLoad(e);
  }
  Entry[] Selected(){return Entries.SelectedItems.Cast<ListViewItem>().Select(x=>(Entry)x.Tag).ToArray();}
  void LoadPlaces(){var roots=new List<string>{"Laufwerke"};foreach(var special in new[]{Environment.SpecialFolder.DesktopDirectory,Environment.SpecialFolder.MyDocuments,Environment.SpecialFolder.UserProfile}){string path=Environment.GetFolderPath(special);if(!String.IsNullOrEmpty(path)&&Directory.Exists(path))roots.Add(path);}try{roots.AddRange(DriveInfo.GetDrives().Select(x=>x.RootDirectory.FullName));}catch{}places.Items.Clear();places.Items.AddRange(roots.Distinct(StringComparer.OrdinalIgnoreCase).Cast<object>().ToArray());}
  public void ShowDrives(){
   updating=true;Entries.BeginUpdate();
   try{Entries.Items.Clear();current=null;SearchInput.Text="";SearchInput.Enabled=false;Address.Text="Laufwerke";selectionText="";NameInput.Text="";State.Text="Laufwerk öffnen und anschließend den gewünschten Ordner auswählen.";
    foreach(var drive in DriveInfo.GetDrives().OrderBy(x=>x.Name,StringComparer.OrdinalIgnoreCase)){
     string path=drive.RootDirectory.FullName;var row=new ListViewItem(path){Tag=new Entry{Path=path,Folder=true}};
     row.SubItems.Add("Laufwerk");row.SubItems.Add("");Entries.Items.Add(row);
    }
   }catch(Exception ex){State.Text="Laufwerke konnten nicht gelesen werden: "+ex.Message;}
   finally{Entries.EndUpdate();updating=false;}
  }
  public bool Navigate(string path){if(path=="Laufwerke"){ShowDrives();return true;}string previousName=NameInput.Text;try{path=Path.GetFullPath(Environment.ExpandEnvironmentVariables(path.Trim().Trim('"')));if(!Directory.Exists(path))throw new IOException("Dieser Ordner ist nicht erreichbar.");bool changed=!String.Equals(current,path,StringComparison.OrdinalIgnoreCase);string query=changed?"":SearchInput.Text;var directories=Directory.GetDirectories(path).Where(x=>MatchesSearch(x,query)).OrderBy(x=>x,StringComparer.CurrentCultureIgnoreCase).ToArray();var files=folders?new string[0]:Directory.GetFiles(path).Where(MatchesFilter).Where(x=>MatchesSearch(x,query)).OrderBy(x=>x,StringComparer.CurrentCultureIgnoreCase).ToArray();updating=true;Entries.BeginUpdate();try{Entries.Items.Clear();foreach(string directory in directories)Add(directory,true);foreach(string file in files)Add(file,false);}finally{Entries.EndUpdate();updating=false;}current=path;if(changed){updating=true;try{SearchInput.Text="";}finally{updating=false;}}SearchInput.Enabled=true;Address.Text=path;selectionText="";NameInput.Text=folders?current:save?previousName:"";State.Text="";return true;}catch(Exception ex){State.Text="Ordner konnte nicht geöffnet werden: "+ex.Message;return false;}}
  public static bool MatchesSearch(string path,string query){string name=Path.GetFileName(path);return (query??"").Split(new[]{' ','\t'},StringSplitOptions.RemoveEmptyEntries).All(word=>name.IndexOf(word,StringComparison.CurrentCultureIgnoreCase)>=0);}
  void Add(string path,bool directory){var row=new ListViewItem(Path.GetFileName(path)){Tag=new Entry{Path=path,Folder=directory}};row.SubItems.Add(directory?"Ordner":Path.GetExtension(path));string size="";if(!directory)try{size=((new FileInfo(path).Length+1023)/1024).ToString("N0")+" KB";}catch{}row.SubItems.Add(size);Entries.Items.Add(row);}
  public bool MatchesFilter(string path){string[] parts=(Filter??"Alle Dateien|*.*").Split('|');int index=FileTypes.SelectedIndex<0?0:FileTypes.SelectedIndex;string pattern=parts.Length>index*2+1?parts[index*2+1]:"*.*";return pattern.Split(';').Any(p=>p=="*.*"||p=="*"||Regex.IsMatch(Path.GetFileName(path),"^"+Regex.Escape(p).Replace("\\*",".*").Replace("\\?",".")+"$",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant));}
  void Up(){if(current==null)return;var parent=Directory.GetParent(current);if(parent!=null)Navigate(parent.FullName);else ShowDrives();}
  protected override bool ProcessCmdKey(ref Message msg,Keys keys){if(keys==(Keys.Alt|Keys.Up)){Up();return true;}if(keys==Keys.F5){if(current==null)ShowDrives();else Navigate(current);LoadPlaces();return true;}return base.ProcessCmdKey(ref msg,keys);}
  public bool AcceptSelection(){try{
   string typed=NameInput.Text.Trim();var selected=Selected();string[] candidates;
   if(typed==selectionText&&selected.Length>0)candidates=selected.Select(x=>x.Path).ToArray();else if(String.IsNullOrEmpty(typed)&&folders&&current!=null)candidates=new[]{current};else if(String.IsNullOrEmpty(typed))throw new IOException("Bitte eine Datei auswählen oder einen Dateinamen eingeben.");else if(Multiselect&&!folders&&!save&&typed.StartsWith("\""))candidates=Regex.Matches(typed,"\"([^\"]+)\"").Cast<Match>().Select(x=>x.Groups[1].Value).ToArray();else candidates=new[]{typed.Trim('"')};
   if(candidates.Length==0||(!Multiselect&&candidates.Length>1))throw new IOException("Bitte eine passende Auswahl treffen.");candidates=candidates.Select(Environment.ExpandEnvironmentVariables).Select(x=>Path.GetFullPath(Path.IsPathRooted(x)?x:Path.Combine(current??throw new IOException("Bitte zuerst ein Laufwerk öffnen."),x))).ToArray();
   if(!folders&&candidates.Length==1&&Directory.Exists(candidates[0])){Navigate(candidates[0]);return false;}
   if(folders){if(candidates.Length!=1||!Directory.Exists(candidates[0]))throw new IOException("Bitte einen vorhandenen Ordner auswählen.");}
   else if(save){if(candidates.Length!=1)throw new IOException("Bitte genau einen Dateinamen eingeben.");string[] parts=(Filter??"").Split('|');int i=Math.Max(0,FileTypes.SelectedIndex)*2+1;if(String.IsNullOrEmpty(Path.GetExtension(candidates[0]))&&parts.Length>i){string pattern=parts[i].Split(';')[0];if(pattern.StartsWith("*.")&&!pattern.Substring(1).Contains("*"))candidates[0]+=pattern.Substring(1);}string name=Path.GetFileName(candidates[0]);if(String.IsNullOrWhiteSpace(name)||name.EndsWith(".")||name.EndsWith(" ")||Regex.IsMatch(name.Split('.')[0],"^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])$",RegexOptions.IgnoreCase)||name.IndexOfAny(new[]{'<','>',':','"','|','?','*'})>=0)throw new IOException("Ungültiger Dateiname.");if(!Directory.Exists(Path.GetDirectoryName(candidates[0])))throw new IOException("Der Zielordner existiert nicht.");if(File.Exists(candidates[0])&&AppMessage.Show(this,"Die Datei existiert bereits:\r\n"+candidates[0]+"\r\nErsetzen?","Datei ersetzen",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return false;}
   else if(candidates.Any(x=>!File.Exists(x)))throw new IOException("Mindestens eine ausgewählte Datei ist nicht mehr vorhanden.");
   FileNames=candidates;FileName=candidates[0];StudioPreferences.SaveFolder(save?"DateiSpeichern":folders?"Ordner":"DateiOeffnen",folders?FileName:Path.GetDirectoryName(FileName));DialogResult=DialogResult.OK;return true;
  }catch(Exception ex){State.Text=ex.Message;return false;}}
  void NewFolder(){if(current==null){State.Text="Bitte zuerst ein Laufwerk oder einen Ordner öffnen.";return;}using(var dialog=new ModernForm{Text="Neuer Ordner",ClientSize=new Size(420,120),FormBorderStyle=FormBorderStyle.FixedDialog,MinimizeBox=false,MaximizeBox=false,StartPosition=FormStartPosition.CenterParent}){var input=new StudioTextBox{Left=12,Top=12,Width=390,Text="Neuer Ordner"};var ok=new Button{Left=160,Top=55,Width=115,Text="Anlegen",DialogResult=DialogResult.OK};var no=new Button{Left=280,Top=55,Width=115,Text="Abbrechen",DialogResult=DialogResult.Cancel};dialog.Controls.AddRange(new Control[]{input,ok,no});dialog.AcceptButton=ok;dialog.CancelButton=no;if(dialog.ShowDialog(this)!=DialogResult.OK)return;try{string name=input.Text.Trim();if(name.Length==0||name=="."||name==".."||name.IndexOfAny(Path.GetInvalidFileNameChars())>=0||name.IndexOfAny(new[]{'/','\\','<','>',':','"','|','?','*'})>=0)throw new IOException("Ungültiger Ordnername.");string path=Path.Combine(current,name);if(Directory.Exists(path)||File.Exists(path))throw new IOException("Dieser Name ist bereits vorhanden.");Directory.CreateDirectory(path);Navigate(path);}catch(Exception ex){State.Text=ex.Message;}}}
 }
